import{_ as e,o as r,c as a,ae as d}from"./chunks/framework.vFbOv2RL.js";const p=JSON.parse('{"title":"套件與 React 支援度","description":"","frontmatter":{},"headers":[],"relativePath":"conventions/packages-react.md","filePath":"conventions/packages-react.md"}'),o={name:"conventions/packages-react.md"};function n(c,t,s,i,h,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="套件與-react-支援度" tabindex="-1">套件與 React 支援度 <a class="header-anchor" href="#套件與-react-支援度" aria-label="Permalink to &quot;套件與 React 支援度&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本專案以 <strong>React 19</strong> 為基準。新增或升級套件時，請確認其 React 支援度並更新本表。</p><hr><h2 id="專案基準" tabindex="-1">專案基準 <a class="header-anchor" href="#專案基準" aria-label="Permalink to &quot;專案基準&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>版本</th></tr></thead><tbody><tr><td><strong>React</strong></td><td>19.2.8（見 package.json）</td></tr><tr><td><strong>React DOM</strong></td><td>19.2.8</td></tr><tr><td><strong>Router</strong></td><td>React Router 7.18.4 Framework Mode（Remix 3 rename）</td></tr><tr><td><strong>Node</strong></td><td><code>&gt;=24.22.1 &lt;25</code>（engines）</td></tr></tbody></table><p>升級 React 大版前，請依下方清單逐項確認 peer 與相容性，並跑 <code>pnpm run lint:ci</code>、<code>pnpm run test</code>。</p><p>RSC / <code>unstable_viteEnvironmentApi</code> is a spike only — not the production path (T-2026-287). Vite is 6.4.3+ (security); TypeScript is 6.0.x; ESLint 9 flat config; Tailwind stays 3.x.</p><hr><h2 id="與-react-直接相關的套件" tabindex="-1">與 React 直接相關的套件 <a class="header-anchor" href="#與-react-直接相關的套件" aria-label="Permalink to &quot;與 React 直接相關的套件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>套件</th><th>用途</th><th>React 支援／備註</th></tr></thead><tbody><tr><td><strong>react-router</strong></td><td>路由與資料</td><td>RR7 Framework Mode；peer React &gt;=18</td></tr><tr><td><strong>@is_tess/components</strong></td><td>UI 元件</td><td>peer React ^18 || ^19；Radix 為其內部依賴</td></tr><tr><td><strong>react</strong>, <strong>react-dom</strong></td><td>核心</td><td>專案鎖定 19.2.x</td></tr><tr><td><strong>@types/react</strong>, <strong>@types/react-dom</strong></td><td>型別</td><td>應與 react 大版一致（19.x）</td></tr></tbody></table><p>Do not introduce a parallel UI kit for the React 19 bump — keep consuming <code>@is_tess/components</code> (peer <code>^18 \\|\\| ^19</code>).</p><hr><h2 id="測試與建置-間接依賴-react" tabindex="-1">測試與建置（間接依賴 React） <a class="header-anchor" href="#測試與建置-間接依賴-react" aria-label="Permalink to &quot;測試與建置（間接依賴 React）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>套件</th><th>用途</th><th>React 支援／備註</th></tr></thead><tbody><tr><td><strong>@testing-library/react</strong></td><td>元件測試</td><td>v16 與 React 19 相容，需 peer @testing-library/dom</td></tr><tr><td><strong>@testing-library/user-event</strong></td><td>使用者操作模擬</td><td>與 RTL 搭配，無額外 React 版本限制</td></tr><tr><td><strong>vitest</strong></td><td>測試執行</td><td>與 React 版本無直接 peer；<strong>Vitest ^4.1.11</strong>（Vite 6 peer）</td></tr><tr><td><strong>msw</strong></td><td>API mock</td><td>無 React peer；Node 18+、Fetch API，與 React 版本無關</td></tr><tr><td><strong>vite</strong></td><td>建置</td><td>無 React peer；<strong>Vite ^6.4.3</strong> (patched <code>server.fs.deny</code> / esbuild; Vite 5 override lifted)</td></tr></tbody></table><hr><h2 id="其他關鍵套件" tabindex="-1">其他關鍵套件 <a class="header-anchor" href="#其他關鍵套件" aria-label="Permalink to &quot;其他關鍵套件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>套件</th><th>用途</th><th>React 支援／備註</th></tr></thead><tbody><tr><td><strong>lucide-react</strong></td><td>圖標</td><td>通常支援 React 16+；升級時查 peer</td></tr><tr><td><strong>class-variance-authority</strong></td><td>樣式變體</td><td>無 React peer，僅型別與 runtime 工具</td></tr><tr><td><strong>zod</strong></td><td>契約 schema</td><td>無 React peer；TypeScript / 任何環境皆可</td></tr><tr><td><strong>tailwindcss</strong></td><td>樣式</td><td>無 React peer；<strong>stay on Tailwind 3.x</strong> (T-2026-281 is separate)</td></tr><tr><td><strong>@sentry/react-router</strong></td><td>錯誤／traces</td><td>peer React &gt;=18、react-router 7.x；DSN 未設時為 no-op</td></tr><tr><td><strong>@fontsource/inter</strong></td><td>字體</td><td>無 React peer；latin woff2 由 Vite 打包</td></tr><tr><td><strong>@fontsource/petrona</strong></td><td>字體</td><td>無 React peer；latin woff2 由 Vite 打包</td></tr></tbody></table><hr><h2 id="維護方式" tabindex="-1">維護方式 <a class="header-anchor" href="#維護方式" aria-label="Permalink to &quot;維護方式&quot;">​</a></h2><ol><li><strong>新增依賴時</strong>：查 npm 該套件 <code>peerDependencies</code> 是否含 <code>react</code> / <code>react-dom</code>，並在本文「與 React 直接相關」或「其他」補一列。</li><li><strong>升級 React 時</strong>：執行 <code>pnpm run check:peers</code>（即 <code>pnpm ls react react-dom</code>），檢查 peer 衝突；依本表與官方遷移指南逐項驗證。</li><li><strong>升級 Radix / React Router / RTL 時</strong>：查該套件 changelog 的 React 要求，並更新本表與 <a href="./../architecture/system-overview.html">system-overview</a> 的 Tech Stack。</li></ol><hr><h2 id="參考" tabindex="-1">參考 <a class="header-anchor" href="#參考" aria-label="Permalink to &quot;參考&quot;">​</a></h2><ul><li><a href="./../architecture/system-overview.html">system-overview</a>：Tech Stack 寫明 React Router 7 Framework Mode + React 19</li><li><strong>package.json</strong>：<code>engines.node</code>、<code>dependencies.react</code> 為單一來源</li></ul>',24)])])}const R=e(o,[["render",n]]);export{p as __pageData,R as default};
